const clean = (value) => String(value ?? '').trim();
const hasValue = (value) => value !== null && value !== undefined && value !== '';
const normalizeHeader = (value) => String(value ?? '').toLowerCase().replace(/[^a-z0-9а-яё]+/g, '');
const gtinKey = (value) => String(value ?? '').replace(/\D/g, '');
const upper = (value) => String(value ?? '').trim().toUpperCase();
const parseNumber = (value) => {
  if (!hasValue(value)) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const normalized = String(value).replace(/\s+/g, '').replace(',', '.').replace(/[^\d.-]/g, '');
  if (!normalized) return null;
  const num = Number(normalized);
  return Number.isFinite(num) ? num : null;
};
const uniq = (arr) => [...new Set(arr.filter(v => hasValue(v)).map(v => String(v).trim()))];
const joinSemi = (arr) => {
  const values = uniq(arr);
  return values.length ? values.join('; ') : null;
};
const round3 = (v) => v === null || v === undefined ? null : Number(Number(v).toFixed(3));
const round2 = (v) => v === null || v === undefined ? null : Number(Number(v).toFixed(2));
const formatDateRu = (d) => {
  if (!(d instanceof Date) || isNaN(d.getTime())) return null;
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const yy = d.getUTCFullYear();
  return `${dd}.${mm}.${yy}`;
};
const parseLotToDate = (lot) => {
  const t = clean(lot);
  const m = t.match(/^(\d{4})(\d{2})(\d{2})$/);
  if (!m) return null;
  const y = Number(m[1]); const mo = Number(m[2]); const d = Number(m[3]);
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (isNaN(dt.getTime())) return null;
  return dt;
};
const addMonthsMinusOneDay = (date, months) => {
  if (!(date instanceof Date) || !Number.isFinite(months)) return null;
  const dt = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + months, date.getUTCDate()));
  dt.setUTCDate(dt.getUTCDate() - 1);
  return dt;
};

