const buildInvoiceMap = (invoiceRows) => {
  const invoiceMap = {};
  for (const row of invoiceRows || []) {
    const gtin = gtinKey(row.gtin);
    if (!gtin) continue;

    if (!invoiceMap[gtin]) {
      invoiceMap[gtin] = {
        gtin,
        lineNos: [],
        vendorCode: clean(row.vendorCode) || null,
        dgFlag: clean(row.dgFlag) || null,
        description: clean(row.description) || null,
        hsCode: clean(row.hsCode) || null,
        quantity: 0,
        amount: 0,
        unitPrice: parseNumber(row.unitPrice),
      };
    }

    const target = invoiceMap[gtin];
    if (hasValue(row.lineNo)) target.lineNos.push(row.lineNo);
    if (!target.vendorCode && hasValue(row.vendorCode)) target.vendorCode = clean(row.vendorCode);
    if (!target.dgFlag && hasValue(row.dgFlag)) target.dgFlag = clean(row.dgFlag);
    if (!target.description && hasValue(row.description)) target.description = clean(row.description);
    if (!target.hsCode && hasValue(row.hsCode)) target.hsCode = clean(row.hsCode);

    target.quantity += parseNumber(row.quantity) || 0;
    target.amount += parseNumber(row.amount) || 0;
    if ((target.unitPrice === null || target.unitPrice === undefined) && hasValue(row.unitPrice)) {
      target.unitPrice = parseNumber(row.unitPrice);
    }
  }
  return invoiceMap;
};

const buildPackingMap = (packingRows) => {
