    const gtin = gtinKey(row.gtin);
    if (!gtin) continue;

    if (!packingMap[gtin]) {
      packingMap[gtin] = {
        gtin,
        rows: [],
        lineNos: [],
        cartonNos: [],
        palletNos: [],
        lots: [],
        quantity: 0,
        netWeight: 0,
        grossWeight: 0,
        dgFlag: clean(row.dgFlag) || null,
        description: clean(row.description) || null,
        vendorCode: clean(row.vendorCode) || null,
      };
    }

    const target = packingMap[gtin];
    target.rows.push(row);
    if (hasValue(row.lineNo)) target.lineNos.push(row.lineNo);
    if (hasValue(row.cartonNo)) target.cartonNos.push(clean(row.cartonNo));
    if (hasValue(row.palletNo)) target.palletNos.push(clean(row.palletNo));
    if (hasValue(row.lot)) target.lots.push(clean(row.lot));

    target.quantity += parseNumber(row.quantity) || 0;
    target.netWeight += parseNumber(row.netWeight) || 0;
    target.grossWeight += parseNumber(row.grossWeight) || 0;
    if (!target.dgFlag && hasValue(row.dgFlag)) target.dgFlag = clean(row.dgFlag);
    if (!target.description && hasValue(row.description)) target.description = clean(row.description);
    if (!target.vendorCode && hasValue(row.vendorCode)) target.vendorCode = clean(row.vendorCode);
  }
  return packingMap;
};

const buildCartonLabelAggregated = (cartonNos) => {
  const labels = [];
  for (const cartonNoRaw of uniq(cartonNos)) {
    const cartonNo = clean(cartonNoRaw);
    if (!cartonNo) continue;
    const shared = globalCartonItemMap[cartonNo] && globalCartonItemMap[cartonNo].size > 1;
    labels.push(USE_PART_FOR_SHARED_CARTONS && shared ? `часть ${cartonNo}` : cartonNo);
  }
  return labels.length ? labels.join('; ') : null;
};

// === CUSTOMS (DG/NDG) — aggregated rows per GTIN, with new columns from master ===
const buildCustomsRowsForGroup = (groupKey, invoiceRows, packingRows) => {
  const invoiceMap = buildInvoiceMap(invoiceRows);
  const packingMap = buildPackingMap(packingRows);
  const allGtins = [...new Set([...Object.keys(invoiceMap), ...Object.keys(packingMap)])].sort();

  const rows = [];
  let index = 1;

  for (const gtin of allGtins) {
    const invoice = invoiceMap[gtin] || null;
    const packing = packingMap[gtin] || null;
    const master = masterByGtin[gtin] || null;

    const warnings = [];
    if (!invoice) warnings.push(`нет строки в invoice для GTIN ${gtin}`);
    if (!packing) warnings.push(`нет строки в packing для GTIN ${gtin}`);
    if (!master) warnings.push(`нет строки в master для GTIN ${gtin}`);

    const invQty = invoice ? Number(invoice.quantity || 0) : null;
    const packQty = packing ? Number(packing.quantity || 0) : null;
    if (invoice && packing && invQty !== packQty) warnings.push(`qty invoice=${invQty}, packing=${packQty}`);

    const netWeight = packing ? round3(packing.netWeight) : null;
    const grossWeight = packing ? round3(packing.grossWeight) : null;
    const netGreaterThanGross =
      WARN_NET_GT_GROSS && netWeight !== null && grossWeight !== null && netWeight > grossWeight;
    if (netGreaterThanGross) warnings.push(`net > gross (${netWeight} > ${grossWeight})`);

    const row = {
      '#': index++,
      'GTIN': gtin ? `'${gtin}` : null,
      'Артикул': invoice?.vendorCode || master?.article || packing?.vendorCode || null,
      'DG/NDG': groupKey === 'CZ' ? (invoice?.dgFlag || packing?.dgFlag || master?.dgFlag || null) : groupKey,
      '№ по инвойсу': joinSemi(invoice?.lineNos || []),
      'кол-во по инв': invoice ? invoice.quantity : null,
      '№ по упак': joinSemi(packing?.lineNos || []),
      'кол-во': packing ? packing.quantity : null,
      'вес НЕТТО': netWeight,
      'вес БРУТТО': grossWeight,
      'коробка': buildCartonLabelAggregated(packing?.cartonNos || []),
      'LOT': packing?.lots?.length ? "'" + uniq(packing.lots).join('; ') : null,
      '№ паллета': joinSemi(packing?.palletNos || []),
      'ТНВЭД': hasValue(master?.customsCode) ? "'" + String(master.customsCode) : null,
      'Product (Eng)': master?.productEng || invoice?.description || packing?.description || null,
      'Product (Rus)': master?.productRus || null,
      'Volume': master?.volume || null,
      'Описание упаковки': master?.packageDescription || null,
      'Цена за шт.': invoice?.unitPrice ?? null,
      'Amount $': invoice ? round2(invoice.amount) : null,
      'Alcohol': master?.alcohol ?? null,
      'SD-Alcohol': master?.sdAlcohol ?? null,
      'ACETON': master?.aceton ?? null,
      'ДС': master?.conformityDoc ?? null,
      'Дата начало': master?.conformityStart ?? null,
      'Дата окончан': master?.conformityEnd ?? null,
      'ЧЗ ДС': null,
      'СРОК ГОДНОСТИ В МЕС.': master?.expiryMonths ?? null,
      'производитель': master?.manufacturer ?? null,
      'страна происхождения': master?.country ?? null,
      'Дата изготовления': (() => { const lots = packing?.lots || []; if (!lots.length) return null; const d = parseLotToDate(lots[0]); return d ? formatDateRu(d) : null; })(),
      'Годен до': (() => { const lots = packing?.lots || []; if (!lots.length) return null; const d = parseLotToDate(lots[0]); if (!d) return null; const m = parseNumber(master?.expiryMonths); if (m == null) return null; return formatDateRu(addMonthsMinusOneDay(d, m)); })(),
      '__row_warning': warnings.length > 0,
      '__warning_net_gt_gross': netGreaterThanGross,
      '__warning_reason': warnings.join(' | ') || null,
    };

    rows.push(row);
  }
  return rows;
};

// === CZ — built from packing rows directly (one packing row = one CZ row) + kit expansion ===
const buildCzRowFromPacking = (packingRow, opts) => {
  opts = opts || {};
  const gtin = gtinKey(opts.overrideGtin || packingRow.gtin);
  const master = masterByGtin[gtin] || null;
  const lot = clean(packingRow.lot);
  const prodDate = parseLotToDate(lot);
  const months = master?.expiryMonths != null ? Number(master.expiryMonths) : null;
  const expDate = (prodDate && Number.isFinite(months)) ? addMonthsMinusOneDay(prodDate, months) : null;

  const qty = parseNumber(packingRow.quantity);
  const finalQty = opts.qtyMultiplier ? (qty != null ? qty * opts.qtyMultiplier : null) : qty;

  const netWeight = round3(packingRow.netWeight);
  const grossWeight = round3(packingRow.grossWeight);
  const netGreaterThanGross =
    WARN_NET_GT_GROSS && netWeight !== null && grossWeight !== null && netWeight > grossWeight;

  return {
    'GTIN': gtin ? `'${gtin}` : null,
    'Артикул': opts.vendorCode || packingRow.vendorCode || master?.article || null,
    'DG/NDG': clean(packingRow.dgFlag) || master?.dgFlag || clean(packingRow.__effectiveCustomsScope) || (opts.scopeMap && opts.scopeMap[clean(packingRow.vendorCode)]) || null,
    'Наименование АНГЛ': opts.nameEng || master?.productEng || packingRow.description || null,
    'Наименование РУС': opts.nameRus || master?.productRus || null,
    'ТНВЭД': hasValue(master?.customsCode) ? "'" + String(master.customsCode) : null,
    'LOT': lot ? `'${lot}` : null,
    'Срок годности': months ?? null,
    'Дата изгот': prodDate ? formatDateRu(prodDate) : null,
    'Годен до': expDate ? formatDateRu(expDate) : null,
    'Кол-во': finalQty,
    'Коробка №': formatCarton(packingRow.cartonNo),
    '№ паллета': hasValue(packingRow.palletNo) ? `PLT №${clean(packingRow.palletNo)}` : null,
    'Data Matrix': 'Да',
    'Размер Этикетки': master?.labelSize || null,
    'Примечание по этикетке': null,
    'Концентрация спирта, % ЭТИЛОВЫЙ СПИРТ (ЭТАНОЛ)': master?.alcohol ?? null,
    'Вложения в наборы': opts.kitNote || null,
    'Цена за шт.': null,
    '__row_warning': netGreaterThanGross,
    '__warning_net_gt_gross': netGreaterThanGross,
    '__warning_reason': netGreaterThanGross ? `net > gross (${netWeight} > ${grossWeight})` : null,
  };
};

const buildCartonRange = (cartonNos) => {
  const valid = cartonNos.filter(Boolean);
  if (!valid.length) return null;
  if (valid.length === 1) return `${valid[0]}; `;
  const nums = valid.map(n => parseNumber(n)).filter(n => n !== null);
  if (nums.length === valid.length) {
    const sorted = [...nums].sort((a, b) => a - b);
    const consecutive = sorted.every((n, i) => i === 0 || n === sorted[i - 1] + 1);
    if (consecutive) return `${sorted[0]}-${sorted[sorted.length - 1]}`;
  }
  return valid.map(c => `${c}; `).join('');
};

const buildCzRows = () => {
  const invoiceScopeByVendor = {};
  const allInvoices = [
    ...(pythonData.dgInvoiceRows || []).map(r => ({ ...r, __scope: 'DG' })),
    ...(pythonData.ndgInvoiceRows || []).map(r => ({ ...r, __scope: 'NDG' })),
  ];
  for (const inv of allInvoices) {
    const vc = clean(inv.vendorCode);
    if (vc && !invoiceScopeByVendor[vc]) invoiceScopeByVendor[vc] = inv.__scope;
  }
  const packingRows = pythonData.czPackingRows || pythonData.packingRows || [];
  const rows = [];

  // Pre-group kit rows by (gtin, lot) so we can aggregate
  const kitGroups = {};
  for (const pr of packingRows) {
    const kit = findKit(pr);
    if (!kit) continue;
    const key = `${gtinKey(pr.gtin)}|${clean(pr.lot)}`;
    if (!kitGroups[key]) kitGroups[key] = { kit, rows: [] };
    kitGroups[key].rows.push(pr);
  }

  const emittedKits = {};
  for (const packingRow of packingRows) {
    const kit = findKit(packingRow);
    if (!kit) {
      // Regular row: one per carton
      rows.push(buildCzRowFromPacking(packingRow, { scopeMap: invoiceScopeByVendor }));
    } else {
      const key = `${gtinKey(packingRow.gtin)}|${clean(packingRow.lot)}`;
      if (emittedKits[key]) continue; // already emitted this kit group
      emittedKits[key] = true;

      const group = kitGroups[key];
      const totalQty = group.rows.reduce((s, r) => s + (parseNumber(r.quantity) || 0), 0);
      const cartonLabel = buildCartonRange(group.rows.map(r => clean(r.cartonNo)));

      // Aggregated kit row (Вложения = empty)
      const kitRow = buildCzRowFromPacking(group.rows[0], { kitNote: null, scopeMap: invoiceScopeByVendor });
      kitRow['Кол-во'] = totalQty;
      kitRow['Коробка №'] = cartonLabel;
      rows.push({ __kitRow: true, ...kitRow });

      // Component rows: one per component, total qty, no carton, no # (marked as component)
      for (const comp of kit.components) {
        const compRow = buildCzRowFromPacking(group.rows[0], {
          overrideGtin: comp.gtin,
          vendorCode: comp.vendorCode,
          nameEng: comp.nameEng,
          nameRus: comp.nameRus,
          qtyMultiplier: null,
          kitNote: '*',
        });
        compRow['Кол-во'] = totalQty * kit.multiplier;
        compRow['Коробка №'] = null;
        rows.push({ __compRow: true, ...compRow });
      }
    }
  }

  // Renumber: kit rows and regular rows get sequential #, component rows get null
  let seq = 1;
  return rows.map(r => {
    const isComp = r.__compRow;
    const { __kitRow, __compRow, ...rest } = r;
    return { '#': isComp ? null : seq++, ...rest };
  });
};

const dgRows = buildCustomsRowsForGroup('DG', pythonData.dgInvoiceRows || [], pythonData.dgPackingRows || []);
const ndgRows = buildCustomsRowsForGroup('NDG', pythonData.ndgInvoiceRows || [], pythonData.ndgPackingRows || []);
