      'Vendor Code',
      'ItemCode',
      'SAP ItemCode'
    ).map(normalizeCode),
  ].filter(Boolean);
  const uniqueItemNos = [...new Set(itemNos)];

  const gtin = gtinToText(
    get(
      'Код товара',
      'Barcode',
      'BARCODE',
      'GTIN',
      'gtin',
      'Штрихкод',
      'Баркод',
      'EAN'
    )
  );

  if (!itemNo && !gtin) return null;

  return {
    itemNo: itemNo || null,
    itemNos: uniqueItemNos,
    article: get(
      'SKU RU',
      'Артикул',
      'АРТИКУЛ',
      'article',
      'Арт. Ру-Бьюти',
      'Артикул РУ'
    ),
    gtin,
    customsCode: get(
      'Customs Code',
      'Код ТНВЭД',
      'Код ТНВЭД ',
      'customsCode',
      'Код ТНВЭД (13933)',
      'ТНВЭД'
    ),
    translation: get(
      'PRODUCT DESCRIPTION RU',
      'Перевод',
      'translation',
      'Полное наименование товара (2478)',
      'Наименование RU',
      'Наименование'
    ) || translationHeuristic || '',
    packageDescription: get(
      'PACKAGE DESCRIPTION RU',
      'Пояснения к материалу и упаковке',
      'ОПИСАНИЕ УПАКОВКИ',
      'packageDescription',
      'Пояснения к материалу и упаковке (для таможни)'
    ) || packageHeuristic || '',
    countryOfOrigin: normalizeCountry(
      get(
        'Country Of Origin',
        'страна происхождения',
        'countryOfOrigin',
        'Страна происхождения'
      )
    ),
    ds: get(
      'Декларация о соответствии (23557)',
      'ДС',
      'СГР/деклация'
    ),
    dt: get(
      'ДТ'
    ),
    tovar: get(
